const b = $input.first().json.body || $input.first().json;

if (!b.siteId) throw new Error('Missing required field: siteId');
if (!b.message) throw new Error('Missing required field: message');

const msg = b.message.toLowerCase().trim();
const actionWords = /\b(implement|create|add|build|make|fix|update|change|edit|delete|remove|install|modify|replace|refactor|style|redesign|adjust|set|configure|enable|disable|write|code)\b/;
const questionWords = /^(what|why|how|can you|could you|should|is it|explain|describe|tell me)/;
const isQuestion = questionWords.test(msg);
const isActionIntent = actionWords.test(msg) && !isQuestion;

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    image: b.image || null,
    images: b.images || (b.image ? [b.image] : []),
    executorMode: b.executorMode || 'auto', // User-selected mode: auto, fast, thinking
    isActionIntent,
    isQuestion
  }
}];

const inp = $('Validate & Detect Intent').item.json;
const rawSite = $input.first().json;

let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found for siteId: ' + inp.siteId);

const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

const siteKey = site.site_key || inp.siteId;
const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

const owner = repoMatch[1];
const repo = repoMatch[2].replace(/\.git$/, '');
const branch = site.default_branch || 'main';
const msg = inp.message.toLowerCase();

// STRICT ROUTING LOGIC
// 1. Creation/Design tasks -> COMPLEX
const isCreation = /\b(create|add|new|design|generate|build|make a page)\b/i.test(msg);
if (isCreation) console.log('Detected CREATION/DESIGN task -> Force COMPLEX');

// 2. Simple Modification -> SIMPLE (only if NOT creation)
// "change X to Y", "fix typo", "update text"
const isStrictlySimple = !isCreation && /^(change|update|replace|set|fix)\s+(?!the\s+layout).{5,50}\s+(to|with|into)\s+/i.test(inp.message);
const isSimple = !isCreation && (isStrictlySimple || /^(change|update|fix)\s+(the\s+)?(title|name|text|color|heading)/i.test(inp.message));

// 3. AGGRESSIVE TOKEN SAVING
const maxFiles = isStrictlySimple ? 1 : (isSimple ? 2 : 4);
console.log('Request type:', isSimple ? 'SIMPLE' : 'COMPLEX', '- fetching', maxFiles, 'files');

// Fetch repo tree
let allFiles = [];
try {
  const tree = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/repos/' + owner + '/' + repo + '/git/trees/' + branch + '?recursive=1',
    headers: { 'Authorization': 'Bearer ' + githubToken },
    timeout: 10000
  });
  allFiles = (tree.tree || []).filter(f => f.type === 'blob' && /\.(tsx?|jsx?)$/.test(f.path) && !f.path.includes('node_modules') && f.size < 30000);
} catch (e) {}

// Score files by relevance
const scored = allFiles.map(f => {
  let score = 0;
  const p = f.path.toLowerCase();
  if (p.includes('page.tsx')) score += 10;
  // LOWER layout score unless heavily implied
  if (p.includes('layout')) score += 1;
  if (msg.includes('layout') || msg.includes('title') || msg.includes('metadata')) score += 10; // Boost if relevant

  if (p.includes('header')) score += 4;
  if (p.includes('footer')) score += 3;
  if (p.includes('src/app/')) score += 2;
  // Boost files matching message words
  for (const w of msg.split(/\s+/).filter(w => w.length > 3)) {
    if (p.includes(w)) score += 20;
  }
  return { path: f.path, score };
}).sort((a, b) => b.score - a.score);

const filesToFetch = scored.slice(0, maxFiles).map(f => f.path);

return [{
  json: {
    ...inp,
    site: { id: siteKey, uuid: site.id, name: site.name || 'Unknown', repo_url: site.repo_url, branch },
    owner, repo, branch,
    previewUrl: 'https://' + siteKey + '.preview.automatelb.com',
    filesToFetch,
    isSimpleRequest: isSimple,
    isComplex: !isSimple,
    fileContents: {},
    contextFiles: [],
    executorMode: inp.executorMode || 'auto',
    githubToken
  }
}];

// Fetch files with token-optimized content limits
const ctx = $('Build Context').item.json;
const files = ctx.filesToFetch || [];
if (files.length === 0) return [{ json: { ...ctx, fileContents: {}, contextFiles: [] } }];

// Dynamic content limit based on request type
const contentLimit = ctx.isSimpleRequest ? 1500 : 2500; // Was 5000
console.log('Fetching', files.length, 'files, limit:', contentLimit, 'chars/file');

const results = await Promise.all(files.map(async (file) => {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/' + ctx.owner + '/' + ctx.repo + '/contents/' + file + '?ref=' + ctx.branch,
      headers: { 'Authorization': 'Bearer ' + ctx.githubToken, 'Accept': 'application/vnd.github.v3.raw' },
      timeout: 8000
    });
    return { path: file, content: typeof response === 'string' ? response : '', success: true };
  } catch (e) {
    return { path: file, success: false };
  }
}));

const fileContents = {};
const contextFiles = [];
for (const r of results.filter(r => r.success && r.content)) {
  fileContents[r.path] = r.content.length > contentLimit ? r.content.substring(0, contentLimit) + '...' : r.content;
  contextFiles.push(r.path);
}

return [{ json: { ...ctx, fileContents, contextFiles, _parallelFetch: true } }];

// Merge Files - now Prepare Fetch does parallel fetching directly
const items = $input.all();
const firstItem = items[0]?.json;

// If Prepare Fetch already did parallel fetching, just pass through
if (firstItem?._parallelFetch || firstItem?.fileContents) {
  // Add loud warning about files in context
  const filesInContext = Object.keys(firstItem.fileContents || {});
  if (filesInContext.length > 0) {
    firstItem._filesInContextWarning = '🔥 CRITICAL: These ' + filesInContext.length + ' files are ALREADY LOADED in your context. DO NOT call read_file for: ' + filesInContext.join(', ');
  }
  return [{ json: firstItem }];
}

// Fallback: Old flow where Fetch Files HTTP node was used
const prepItems = $('Prepare Fetch').all();
const ctx = prepItems[0]?.json?._ctx || prepItems[0]?.json || firstItem;
if (!ctx) return [{ json: { error: 'Lost context', fileContents: {}, contextFiles: [] } }];

const fileContents = ctx.fileContents || {};
const contextFiles = ctx.contextFiles || [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const path = prepItems[i]?.json?.currentFile || item.path;
  if (!path || fileContents[path]) continue;
  if (item.content) {
    try {
      const decoded = Buffer.from(item.content, 'base64').toString('utf8');
      fileContents[path] = decoded.length > 3000 ? decoded.substring(0, 3000) + '\n// ...truncated' : decoded;
      contextFiles.push(path);
    } catch (e) {}
  }
}

// Add warning
const filesInContext = Object.keys(fileContents);
if (filesInContext.length > 0) {
  ctx._filesInContextWarning = '🔥 CRITICAL: These ' + filesInContext.length + ' files are ALREADY LOADED. DO NOT call read_file for: ' + filesInContext.join(', ');
}

return [{ json: { ...ctx, fileContents, contextFiles } }];

// Fetch recent memory for this project from Supabase
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const requestId = ctx.requestId || 'unknown';
const conversationId = ctx.conversationId || null;

if (!siteId) {
  return [{ json: { ...ctx, memoryContext: 'First request.' } }];
}

// Insert initial thinking step
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      request_id: requestId,
      site_id: siteId,
      conversation_id: conversationId,
      step_number: 1,
      tool_name: 'analyze',
      status: 'running',
      message: 'Analyzing...',
      details: { message: ctx.message }
    }),
    timeout: 5000
  });
} catch (e) {}

try {
  let memoryUrl = 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/agent_memory?project_id=eq.' + siteId;
  if (conversationId) {
    memoryUrl += '&or=(session_id.eq.' + conversationId + ',session_id.is.null)';
  }
  memoryUrl += '&order=created_at.desc&limit=5';

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: memoryUrl,
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4'
    },
    timeout: 10000
  });

  let memoryContext = 'First request.';
  if (Array.isArray(response) && response.length > 0) {
    // Ultra-compressed format: msg→[files]→result
    memoryContext = response.reverse().map(function(e) {
      const d = e.content_json || {};
      const msg = (d.message || '').slice(0, 50);
      const files = (d.filesModified || []).concat(d.filesCreated || []).map(f => f.split('/').pop()).join(',');
      const result = (d.summary || 'ok').slice(0, 60);
      return msg + '→[' + files + ']→' + result;
    }).join('\n');
  }

  return [{ json: { ...ctx, memoryContext: memoryContext } }];
} catch (e) {
  return [{ json: { ...ctx, memoryContext: 'First request.' } }];
}

// HTTP-BASED COMPLEX EXECUTOR V5 - TOKEN OPTIMIZED
const ctx = $input.item.json;
const ANTHROPIC_KEY = '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';
const MODEL = 'claude-sonnet-4-5-20250929';

const TOOLS = [
    { name: 'write_file', description: 'Write complete file. Use for any change.', input_schema: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] }, cache_control: { type: 'ephemeral' } },
    { name: 'str_replace', description: 'Single line swap only', input_schema: { type: 'object', properties: { file: { type: 'string' }, old_text: { type: 'string' }, new_text: { type: 'string' } }, required: ['file', 'old_text', 'new_text'] }, cache_control: { type: 'ephemeral' } },
    { name: 'list_files', description: 'List dir', input_schema: { type: 'object', properties: { dir: { type: 'string' } }, required: ['dir'] }, cache_control: { type: 'ephemeral' } },
    { name: 'read_file', description: 'Read file', input_schema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] }, cache_control: { type: 'ephemeral' } }
];

const SYSTEM = [{ type: 'text', text: 'You are a code editor. CRITICAL: The FILES section below contains all project code ALREADY LOADED. DO NOT ask for files or code samples - USE THE FILES BELOW. Just use write_file to make changes. Complete in 1-2 tool calls. Reply plain text, no markdown, be brief.', cache_control: { type: 'ephemeral' } }];

let consecutiveErrors = 0;

const executeTool = async (name, input) => {
    const siteId = ctx.site?.id;
    const githubToken = ctx.githubToken;
    if (!siteId) return 'FATAL: No siteId';

    if (name === 'str_replace') {
        try {
            const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/replace', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.file, search: input.old_text, replace: input.new_text, githubToken }), timeout: 15000, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true });
            if (r.statusCode >= 400) { consecutiveErrors++; return 'ERROR: ' + JSON.stringify(r.body || r.statusCode); }
            consecutiveErrors = 0;
            return JSON.stringify({ success: true, file: input.file, action: 'replaced' });
        } catch (e) { consecutiveErrors++; return 'ERROR: ' + e.message; }
    }

    if (name === 'write_file') {
        try {
            const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/write', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.path, content: input.content, githubToken }), timeout: 20000, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true });
            if (r.statusCode >= 400) { consecutiveErrors++; return 'ERROR: ' + JSON.stringify(r.body || r.statusCode); }
            consecutiveErrors = 0;
            return JSON.stringify({ success: true, file: input.path, action: 'created' });
        } catch (e) { consecutiveErrors++; return 'ERROR: ' + e.message; }
    }

    if (name === 'list_files') {
        try {
            const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.github.com/repos/' + ctx.owner + '/' + ctx.repo + '/contents/' + (input.dir || 'src') + '?ref=' + ctx.branch, headers: { 'Authorization': 'Bearer ' + githubToken }, timeout: 10000, json: true });
            return Array.isArray(r) ? r.map(f => f.path).join('\n') : 'Error';
        } catch (e) { return 'ERROR: ' + e.message; }
    }

    if (name === 'read_file') {
        if (ctx.fileContents?.[input.path]) return ctx.fileContents[input.path].slice(0, 3000);
        try {
            const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/read', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.path, githubToken }), timeout: 10000, json: true });
            return (r.content || '').slice(0, 3000);
        } catch (e) { return 'ERROR: ' + e.message; }
    }

    return 'Unknown tool';
};

const callClaude = async (msgs) => {
    return await this.helpers.httpRequest({ method: 'POST', url: 'https://api.anthropic.com/v1/messages', headers: { 'x-api-key': ANTHROPIC_KEY, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'prompt-caching-2024-07-31', 'content-type': 'application/json' }, body: JSON.stringify({ model: MODEL, max_tokens: 1536, system: SYSTEM, tools: TOOLS, messages: msgs }), timeout: 60000, json: true });
};

const fileCtx = Object.entries(ctx.fileContents || {}).slice(0, 3).map(([f, c]) => f + ':\n' + c.slice(0, 2000)).join('\n---\n');
const memCtx = ctx.memoryContext ? '\nHISTORY:' + ctx.memoryContext : '';
const baseMsg = ctx.message + memCtx;
const fullMsg = baseMsg + (fileCtx ? '\n\nFILES:\n' + fileCtx : '');
const messages = [{ role: 'user', content: fullMsg }];

let output = ''; let steps = []; let i = 0;

while (i++ < 6) {
    if (consecutiveErrors >= 2) { output = 'Stopped: errors.'; break; }
    const r = await callClaude(messages);
    if (r.error) { output = 'Error: ' + JSON.stringify(r.error); break; }
    if (r.usage) console.log('Tokens:', r.usage.input_tokens, 'out:', r.usage.output_tokens, 'cached:', r.usage.cache_read_input_tokens || 0);
    const tool = r.content?.find(c => c.type === 'tool_use');
    if (!tool) { output = r.content?.find(c => c.type === 'text')?.text || 'Done'; break; }
    const result = await executeTool(tool.name, tool.input);
    steps.push({ tool: tool.name, input: tool.input, result: result.slice(0, 150) });
    if (result.startsWith('FATAL:')) { output = result; break; }
    messages.push({ role: 'assistant', content: r.content });
    messages.push({ role: 'user', content: [{ type: 'tool_result', tool_use_id: tool.id, content: result }] });
    if (messages[0].content.length > baseMsg.length) { messages[0].content = baseMsg + '\n(files pruned)'; }
}

return [{ json: { ...ctx, output, intermediateSteps: steps, iterations: i } }];

// Save compressed memory entry to Supabase for future context
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const conversationId = ctx.conversationId || null;

if (!siteId) {
  console.log('No site UUID found, skipping memory save');
  return [{ json: ctx }];
}

// Create compressed summary (token-efficient format)
const files = [...(ctx.filesModified || []), ...(ctx.filesCreated || [])].slice(0, 3);
const fileStr = files.length > 0 ? ' [' + files.join(', ') + ']' : '';

// Compress the summary to essential info only
let compressedSummary = '';
const fullSummary = ctx.plan?.humanSummary || '';
if (fullSummary) {
  // Extract first sentence or first 100 chars
  const firstSentence = fullSummary.match(/^[^.!?]*[.!?]/);
  compressedSummary = firstSentence ? firstSentence[0] : fullSummary.substring(0, 100);
}

const memoryEntry = {
  project_id: siteId,
  session_id: conversationId,
  memory_type: 'conversation',
  content: (ctx.message || '').substring(0, 100) + ' → ' + compressedSummary.substring(0, 150) + fileStr,
  content_json: {
    message: (ctx.message || '').substring(0, 150),
    summary: compressedSummary,
    filesModified: (ctx.filesModified || []).slice(0, 5),
    filesCreated: (ctx.filesCreated || []).slice(0, 5),
    filesDeleted: (ctx.filesDeleted || []).slice(0, 5),
    toolsUsed: [...new Set(ctx.toolsUsed || [])].slice(0, 5),
    iterations: ctx.iterations || 0,
    requestId: ctx.requestId || null,
    wasSimple: ctx.isComplex === false
  }
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/agent_memory',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify(memoryEntry),
    timeout: 10000
  });
  console.log('Memory saved (compressed) for session ' + conversationId);
} catch (e) {
  console.error('Memory save failed:', e.message);
}

return [{ json: ctx }];

// Save successful plan to request_cache for next time
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const requestHash = ctx.requestHash;
const cacheHit = ctx.cacheHit;

// Skip if no hash, cache hit, or is a direct response
if (!siteId || !requestHash || cacheHit || ctx.isDirectResponse) {
  return [{ json: ctx }];
}

const planToCache = ctx.executionPlan || { tasks: [] };
const filesModified = [...(ctx.filesModified || []), ...(ctx.filesCreated || [])].slice(0, 10);

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/request_cache',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      site_id: siteId,
      request_hash: requestHash,
      original_message: (ctx.message || '').slice(0, 200),
      plan_json: planToCache,
      files_modified: filesModified
    }),
    timeout: 5000
  });
  console.log('Cached plan for hash:', requestHash);
} catch (e) {
  console.log('Cache save failed:', e.message);
}

return [{ json: ctx }];

const ctx = $('Fetch Memory').item.json;

let raw;
try { raw = $('Simple Executor')?.item?.json; } catch (e) {}
if (!raw?.output) { try { raw = $('Complex Executor')?.item?.json; } catch (e) {} }
if (!raw) raw = $input.item.json;

const output = (raw?.output || '');
const steps = raw?.intermediateSteps || [];

const filesModified = new Set();
const filesCreated = new Set();
const filesDeleted = new Set();
const toolCalls = [];

for (const step of steps) {
  // FIX: Handle both langchain format (action.tool) and HTTP format (tool)
  if (step.action?.tool) toolCalls.push(step.action.tool);
  if (step.tool) toolCalls.push(step.tool);

  // FIX: Check both observation (langchain) AND result (HTTP executors)
  const obs = step.observation || step.result;
  let result = null;

  try {
    if (typeof obs === 'object' && obs !== null) {
       result = obs;
